        for l in d:
            if l.startswith(('+', '-')) and not l.startswith(('+++', '---')):
                print('      %s' % l.strip()[:170])


def sections(path):
    out, cur, buf = {}, '(preamble)', []
    for line in open(path, encoding='utf-8'):
        if re.match(r'^#{1,4} ', line):
            out[cur] = ''.join(buf); cur, buf = line.strip(), []
        else:
            buf.append(line)
    out[cur] = ''.join(buf)
    return out


